TF·IDF : basé sur la fréquence des termes
Recherche probabiliste : estimation de la probabilité de pertinence par terme
LSI : estimation linéaire de concepts latents

\(\Rightarrow\) L’embedding est une estimation linéaire à partir des propriétés de chaque terme.




La caractérisation (embedding) d’un terme est dérivée du contexte (phrase) dans lequel il apparaît
L’embedding aide à prédire le terme dans son contexte
Utilisation du Machine Learning pour la prédiction

\(\Rightarrow\) Les termes co-occurrents dans le même contexte (ex. synonymes) reçoivent un embedding similaire.
// Diagramme : Contenu vs Contexte
#cetz.canvas({
  import cetz.draw: *

  // Contenu
  rect((0, 3), (rel: (4, 1.5)), fill: rgb("#89b4fa"), stroke: rgb("#1e1e2e"), name: "cont", radius: 0.15)
  content((2, 4.2), [*Basé sur le contenu*], anchor: "center")
  content((2, 3.5), [TF·IDF, BIR, LSI], anchor: "center")

  // Contexte
  rect((6, 3), (rel: (4, 1.5)), fill: rgb("#a6e3a1"), stroke: rgb("#1e1e2e"), name: "ctx", radius: 0.15)
  content((8, 4.2), [*Basé sur le contexte*], anchor: "center")
  content((8, 3.5), [Word2Vec, GloVe], anchor: "center")

  // Embedding
  rect((3, 0.5), (rel: (4, 1.2)), fill: rgb("#cba6f7"), stroke: rgb("#1e1e2e"), name: "emb", radius: 0.15)
  content((5, 1.1), [Embedding $v_w in RR^N$], anchor: "center")

  // Différences
  content((2, 2.2), [Fréquence / Linéaire], anchor: "center")
  content((8, 2.2), [Prédiction / Non-linéaire], anchor: "center")

  line("cont", "emb", mark: (end: "&gt;", fill: black))
  line("ctx", "emb", mark: (end: "&gt;", fill: black))
})
#cetz.canvas({
  import cetz.draw: *

  // Catppuccin Mocha palette
  let base    = rgb("#1e1e2e")
  let mantle  = rgb("#181825")
  let crust   = rgb("#11111b")
  let textc   = rgb("#cdd6f4")
  let blue    = rgb("#89b4fa")
  let green   = rgb("#a6e3a1")
  let mauve   = rgb("#cba6f7")
  let peach   = rgb("#fab387")
  let red     = rgb("#f38ba8")
  let surface = rgb("#45475a")

  // Background panel (optional, for clear catppuccin look)
  rect((-0.9, 0.2), (rel: (13.8, 7.2)), fill: base, stroke: crust, radius: 0.12)

  // Left context vectors: w_c1, w_c2, ..., w_cm
  rect((0.0, 5.1), (rel: (0.55, 1.8)), stroke: textc, fill: mantle, name: "wc1", radius: 0.06)
  rect((0.0, 3.0), (rel: (0.55, 1.8)), stroke: textc, fill: mantle, name: "wc2", radius: 0.06)
  rect((0.0, 0.9), (rel: (0.55, 1.8)), stroke: textc, fill: mantle, name: "wcm", radius: 0.06)

  content((-0.35, 6.0), text(textc)[$w_(c_1)$], anchor: "east")
  content((-0.35, 3.9), text(textc)[$w_(c_2)$], anchor: "east")
  content((-0.35, 1.8), text(textc)[$w_(c_m)$], anchor: "east")
  content((0.24, 2.45), text(textc)[$\vdots$], anchor: "center")

  // Merge points
  circle((2.25, 4.9), radius: 0.04, fill: peach, stroke: peach, name: "n1")
  circle((2.25, 2.5), radius: 0.04, fill: peach, stroke: peach, name: "n2")

  // Crossed connections from contexts
  line((0.55, 6.0), "n1", stroke: blue)
  line((0.55, 3.9), "n1", stroke: blue)
  line((0.55, 1.8), "n1", stroke: blue)

  line((0.55, 6.0), "n2", stroke: blue)
  line((0.55, 3.9), "n2", stroke: blue)
  line((0.55, 1.8), "n2", stroke: blue)

  // W block
  rect((2.7, 2.1), (rel: (2.8, 2.9)), stroke: textc, fill: surface, name: "W", radius: 0.08)
  content((4.1, 3.55), text(textc)[$W$], anchor: "center")
  line("n1", (2.7, 4.75), stroke: green)
  line("n2", (2.7, 2.35), stroke: green)

  // Central thin bars (h and c)
  rect((5.95, 2.0), (rel: (0.45, 3.2)), stroke: textc, fill: mauve, name: "hbar", radius: 0.05)
  rect((6.65, 2.0), (rel: (0.45, 3.2)), stroke: textc, fill: mauve, name: "cbar", radius: 0.05)

  content((6.17, 5.45), text(textc)[$h$], anchor: "center")
  content((6.87, 3.55), text(textc)[$c$], anchor: "center")

  line((5.5, 4.75), (5.95, 5.0), stroke: green)
  line((5.5, 2.35), (5.95, 2.2), stroke: green)
  line((5.5, 4.75), (6.65, 2.2), stroke: red)
  line((5.5, 2.35), (6.65, 5.0), stroke: red)

  // W' block
  rect((7.8, 2.1), (rel: (2.8, 2.9)), stroke: textc, fill: surface, name: "Wp", radius: 0.08)
  content((9.2, 3.55), text(textc)[$W'$], anchor: "center")

  line((7.1, 5.0), (7.8, 4.1), stroke: blue)
  line((7.1, 2.2), (7.8, 3.0), stroke: blue)

  // Output column
  rect((11.35, 1.0), (rel: (0.62, 5.8)), stroke: textc, fill: mantle, name: "out", radius: 0.06)
  line((10.6, 4.1), (11.35, 6.3), stroke: peach)
  line((10.6, 3.0), (11.35, 1.5), stroke: peach)

  content((12.05, 6.95), text(peach)[*softmax*], anchor: "west")
  content((12.05, 4.0), text(textc)[$N$], anchor: "west")
  content((12.05, 1.1), text(textc)[$w_T$], anchor: "west")
})

